    set(body,'grid-template-columns','minmax(0,.465fr) minmax(0,.535fr)');set(body,'height','auto');set(body,'min-height','0');set(body,'align-items','start');set(body,'gap','12px');set(left,'display','block');set(left,'height','auto');set(left,'min-height','0');set(left,'padding','10px 12px 22px');
    const blocks=[...left.querySelectorAll(':scope>.format2-block')];
